"""Generate a self-contained report only from passing local backend evidence."""
import base64, datetime, hashlib, html, json, pathlib, re
ROOT=pathlib.Path(__file__).resolve().parent.parent
OUT=ROOT/'artifacts/backend-qa'
def load(name): return json.loads((OUT/name).read_text())
tests=load('tests.json')
assert tests['success'] and tests['numFailedTests']==0 and tests['numPendingTests']==0 and tests['numPassedTests']==tests['numTotalTests']
backend=[a for suite in tests['testResults'] if '/tests/backend/' in suite['name'] for a in suite['assertionResults']]
assert backend and all(a['status']=='passed' for a in backend)
private=load('browser-results.json');backup=load('backup-results.json');package=load('package-results.json')
for evidence in [private,backup,package]: assert evidence['checks'] and all(c['passed'] for c in evidence['checks'])
audit=load('audit.json');assert sum(audit['metadata']['vulnerabilities'].values())==0
for name,marker in [('typecheck-owned.log','@unlock/web@ typecheck'),('format.log','All matched files'),('build.log','built in'),('install.log','Lockfile is up to date')]: assert marker in (OUT/name).read_text(),name
web=[]
for folder in ['vault-qa','csv-qa']:
    result=json.loads((ROOT/'artifacts'/folder/'browser-results.json').read_text());assert all(c['passed'] for c in result['checks']);web+=result['checks']
axe_files=list((ROOT/'artifacts/vault-qa').glob('*-axe.json'))+list((ROOT/'artifacts/csv-qa').glob('*-axe.json'))
assert axe_files and all(not json.loads(p.read_text()) for p in axe_files)
http=[]
for name in ['demo-http-dev.log','demo-http-production.log']:
    count=re.search(r'"passed": (\d+)',(OUT/name).read_text());assert count;http.append(int(count.group(1)))
sources=[p for folder in ['apps/server/src','packages/protocol/src','packages/sdk/src'] for p in (ROOT/folder).glob('*.ts')]
assert all(p.stat().st_mtime*1000<=tests['startTime'] for p in sources),'Code changed after the recorded test run'
hashes={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sources}
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
summary={'verifiedAt':now,'tests':tests['numPassedTests'],'backendTests':len(backend),'demoTests':tests['numPassedTests']-len(backend),'privateBrowserChecks':len(private['checks']),'demoBrowserChecks':len(web),'backupChecks':len(backup['checks']),'packageChecks':len(package['checks']),'axeScans':len(axe_files),'axeViolations':0,'dependencyAdvisories':0,'demoHttpChecks':http,'typecheck':'backend, protocol, SDK, web and backend tests passed; workspace-wide check blocked by a concurrently created apps/agent scaffold with no source inputs','sourceHashes':hashes}
(OUT/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
esc=html.escape
def items(rows,key): return ''.join('<li>'+esc(row[key])+'</li>' for row in rows)
deps=load('dependencies.json')
licenses=''.join('<tr><td>'+esc(d['usedBy'])+'</td><td>'+esc(d['name'])+'</td><td>'+esc(d['version'])+'</td><td>'+esc(d['license'])+'</td></tr>' for d in deps)
layouts=load('docs-results.json');assert layouts['checks'] and all(c['passed'] for c in layouts['checks'])
images=''.join('<figure style="margin:24px 0"><img style="display:block;width:100%;height:auto;max-width:'+width+';border:1px solid #d1d9e6" alt="'+esc(label)+'" src="data:image/png;base64,'+base64.b64encode((OUT/name).read_bytes()).decode()+'"><figcaption>'+esc(label)+'</figcaption></figure>' for name,label,width in [('backend-verification-1440.png','Actual report rendering in isolated Chromium · desktop','1050px'),('backend-implementation-375.png','Operator runbook · 375px phone viewport','375px')])
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unlock backend verification</title><style>body{{margin:0;background:#f5f7fb;color:#202b42;font:16px/1.65 system-ui}}main{{max-width:1050px;margin:auto;padding:48px 24px}}h1{{font-size:clamp(34px,5vw,50px);line-height:1.1;letter-spacing:-1.3px}}h2{{margin-top:36px}}.note{{padding:20px;background:#e5edff;border-left:4px solid #244bdc}}.facts{{display:flex;flex-wrap:wrap;gap:28px;margin:30px 0}}.facts strong{{display:block;font-size:34px;line-height:1.2}}.facts span{{font-size:13px}}a{{color:#2043b0}}li{{margin:8px 0}}details{{background:white;padding:18px 22px;border:1px solid #d1d9e6;border-radius:8px;margin:20px 0}}summary{{cursor:pointer;font-weight:600}}code{{overflow-wrap:anywhere}}table{{border-collapse:collapse;width:100%;font-size:13px}}td,th{{text-align:left;padding:10px;border-bottom:1px solid #d1d9e6}}.table{{overflow:auto}}footer{{margin-top:40px;color:#4d5d75}}:focus-visible{{outline:3px solid #244bdc;outline-offset:4px}}</style></head><body><main>
<p>UNLOCK / MEASURED BACKEND EVIDENCE</p><h1>Encrypted custody. Tested boundaries.</h1><p>The separate backend and SDK are implemented. The existing password-manager web preview remains synthetic.</p>
<div class="note"><strong>Verified with generated fixtures, real PostgreSQL/HTTP and isolated Chromium.</strong> No real credentials, external account logins, live KMS/1Password calls, paid APIs, publishing or deployment. This is not independent security certification or approval for production secrets.</div>
<div class="facts"><div><strong>{summary['tests']}</strong><span>tests passed · {len(backend)} backend + {summary['demoTests']} demo</span></div><div><strong>{len(web)+len(private['checks'])}</strong><span>browser checks · {len(web)} UI + {len(private['checks'])} private adapter</span></div><div><strong>0</strong><span>reported dependency advisories</span></div><div><strong>{len(axe_files)}</strong><span>web-preview axe scans · zero violations</span></div></div>
<p><a href="backend-implementation.html">Implementation and operator runbook</a> · <a href="../packages/sdk/README.md">SDK guide</a> · <a href="verification.html">Current web screenshots and evidence</a></p>
<h2>What was actually exercised</h2><ul><li>Real Postgres migrations, encrypted rows, tenant/access boundaries, expected revisions, full 1,000-row password-bearing CSV import, atomic capacity rollback and repeat-commit receipts.</li><li>Owner login through a controlled upstream OIDC provider, signature/nonce/state/PKCE checks, wrong-owner rejection, CSRF and recent-auth requirements.</li><li>Actual HTTP agent OAuth authorization, code replay prevention, refresh rotation/replay rejection, live client revocation and owner/runtime API separation.</li><li>Verified destination sessions, CAS races, cookie deletion/sign-out, source failure, expired worker claims, in-flight revocation fencing, bounded retries and shared private SSO parent serialization/checkpointing.</li><li>Compiled server termination/restart, key rewrapping and decryption under the replacement key, encrypted private OAuth file storage and cross-instance locking.</li><li>Actual <code>pg_dump</code>, no plaintext canaries in the dump, and restore into a separate database with credential/session recovery using retained key material.</li><li>Private CDP adapter in {esc(private['browser'])}: host-only/domain, path, Secure/HttpOnly/SameSite and partition semantics; deletion/rotation; unrelated-domain preservation; target/context mismatch rejection.</li><li>New SDK entry points installed from packed tarballs in an isolated consumer. CLI help/schema/dry-run require no credentials; operator authorization is gated and ordinary CLI/MCP surfaces expose metadata only.</li></ul>
<h2>Build and regression gates</h2><p>Frozen-lockfile installation, scoped protocol/SDK/backend/web and backend-test typechecks, formatting, backend/SDK/web production builds, and all {summary['tests']} tests passed with no skipped tests in the recorded run. The final workspace-wide typecheck is separately blocked by a concurrently created <code>apps/agent</code> scaffold with no source inputs (TS18003); that unrelated work was not edited. Its failure is retained in <code>typecheck.log</code>, while the passing scoped checks are in <code>typecheck-owned.log</code>. The original UI additionally passed {len(web)} production browser checks, {' + '.join(map(str,http))} real HTTP checks across development/production, and {len(axe_files)} axe scans with zero violations. No personal Chrome profile was used.</p>
<p>Two multi-I/O tests initially exceeded their five-second test budgets during heavy host memory/CPU contention. The final run bounds Vitest concurrency to two workers and gives the two full-flow integration cases twenty seconds, without changing their assertions or production deadlines. SDK package-consumer verification also required selecting pnpm 10 rather than the host's global pnpm 11; the final tarball imports passed.</p><p>Important issues caught and fixed during implementation: OAuth mount-prefix handling, normalization of single versus multiple Set-Cookie headers, stale-worker publication, refresh/code replay, private-parent conflicts, preserving tool results after sync failure, fail-closed browser recovery, and an outdated test-only Undici version. The final lockfile audit reports zero known advisories; this does not establish supply-chain or application security.</p>
<details><summary>All {len(backend)} backend/SDK tests</summary><ol>{items(backend,'fullName')}</ol></details>
<details><summary>Private Chromium, backup/restore and packaged-consumer checks</summary><ol>{items(private['checks']+backup['checks']+package['checks'],'check')}</ol></details>
<details><summary>Installed dependency versions and declared licenses</summary><p>These are package metadata, not a legal opinion or certification of provider service terms. No private package was published.</p><div class="table"><table><thead><tr><th>Used by</th><th>Package</th><th>Version</th><th>Declared license</th></tr></thead><tbody>{licenses}</tbody></table></div></details>
<h2>What is not claimed</h2><ul><li>The current TanStack UI is not wired to real custody. Its CSV dialog still discards passwords. Use only fictional data in that preview.</li><li>No live owner IdP, 1Password account or AWS KMS integration was exercised. Those require operator authorization and environment-specific testing.</li><li>Only the configurable fixed-origin JSON/form recipe is shipped. Provider-specific browser/Google SSO, MFA, CAPTCHA, passkeys and device-bound sessions require reviewed implementations. Unsupported flows challenge instead of pretending success.</li><li>Runtime affinity is fail-closed, not a cross-host browser dispatcher. The MCP helper needs the host's maintained, authenticated transport; no standalone MCP server is bundled.</li><li>Module boundaries are not an OS sandbox. A model must not receive unrestricted access to the credential-owning process, files, raw CDP or secret-bearing APIs.</li><li>Revocation cannot retract cookies already delivered or guarantee upstream logout. Fencing prevents stale database publication, not cancellation of already-sent provider requests.</li><li>Production load, edge policy, logging/IAM, real disaster recovery and independent security review remain activation gates. Firefox, Safari, screen readers and real touch hardware are not certified by these checks.</li></ul>
<h2>Evidence</h2><p><code>artifacts/backend-qa/</code> contains the test JSON/log, gate logs, dependency audit, private-browser checks, dump/restore checks, package checks and source hashes. <code>scripts/write-backend-verification.py</code> refuses failed/skipped evidence or production code changed after the recorded tests. Web screenshots are embedded in the linked web report. This backend report is self-contained and uses no external assets or scripts.</p>
<details><summary>Document rendering evidence</summary><p>Both HTML documents passed layout checks at 375 and 1440px without horizontal overflow. These screenshots show the real rendered documents, not backend/provider certification.</p>{images}</details><footer>Generated {now}. Direct implementation; no delegation, commits, pushes or deployment. <code>docs/unlock-discussion.html</code> and the pre-existing <code>codedb.snapshot</code> remain untouched.</footer></main></body></html>'''
(ROOT/'docs/backend-verification.html').write_text(page)
print(json.dumps({k:v for k,v in summary.items() if k!='sourceHashes'},indent=2))
